ALTER TABLE preview_grants ADD COLUMN public_demo INTEGER NOT NULL DEFAULT 0;
CREATE TABLE preview_limits(key TEXT PRIMARY KEY,requests INTEGER NOT NULL,window_start INTEGER NOT NULL);

-- Retained independently of users so deletion cannot reopen first-owner setup.
CREATE TABLE owner_setup (singleton INTEGER PRIMARY KEY CHECK(singleton=1), claim_id TEXT NOT NULL);
INSERT INTO owner_setup SELECT 1,'existing-installation' WHERE EXISTS(SELECT 1 FROM users) OR EXISTS(SELECT 1 FROM projects);
-- Imports and registration also close first-owner setup permanently.
CREATE TRIGGER owner_setup_on_user AFTER INSERT ON users BEGIN
 INSERT INTO owner_setup(singleton,claim_id) VALUES(1,'existing-installation') ON CONFLICT(singleton) DO NOTHING;
END;
CREATE TRIGGER owner_setup_on_project AFTER INSERT ON projects BEGIN
 INSERT INTO owner_setup(singleton,claim_id) VALUES(1,'existing-installation') ON CONFLICT(singleton) DO NOTHING;
END;

UPDATE project_settings
SET settings_json=json_set(settings_json,'$.retired_inbound_address',(SELECT inbound_address FROM email_settings WHERE email_settings.project_id=project_settings.project_id),'$.mailbox_archived_at',json_extract(settings_json,'$.deleted_at')),updated_at=coalesce(json_extract(settings_json,'$.deleted_at'),updated_at)
WHERE json_extract(settings_json,'$.deleted_at') IS NOT NULL
  AND EXISTS(SELECT 1 FROM email_settings WHERE email_settings.project_id=project_settings.project_id AND inbound_address IS NOT NULL);

UPDATE email_settings
SET inbound_address=NULL,is_enabled=0,updated_at=coalesce((SELECT json_extract(settings_json,'$.deleted_at') FROM project_settings WHERE project_settings.project_id=email_settings.project_id),updated_at)
WHERE project_id IN(SELECT project_id FROM project_settings WHERE json_extract(settings_json,'$.deleted_at') IS NOT NULL);

CREATE UNIQUE INDEX IF NOT EXISTS email_settings_active_inbound_ci
ON email_settings(lower(inbound_address))
WHERE is_enabled=1 AND inbound_address IS NOT NULL;

-- Erased message rows keep their identity, revision and frontier; only content is removed.
ALTER TABLE messages ADD COLUMN erased_at INTEGER;
-- Non-identifying erasure audit: who requested it, when, and how many records were removed.
CREATE TABLE contact_erasures(project_id TEXT NOT NULL,contact_id TEXT NOT NULL,erased_by TEXT NOT NULL,erased_at INTEGER NOT NULL,last_erased_at INTEGER NOT NULL,runs INTEGER NOT NULL DEFAULT 1,conversations INTEGER NOT NULL DEFAULT 0,messages INTEGER NOT NULL DEFAULT 0,attachments INTEGER NOT NULL DEFAULT 0,tracked_events INTEGER NOT NULL DEFAULT 0,context_records INTEGER NOT NULL DEFAULT 0,sessions INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(project_id,contact_id));
-- Durable R2 deletion ledger: staged before objects are deleted, cleared by the atomic D1 erasure.
CREATE TABLE contact_erasure_objects(project_id TEXT NOT NULL,contact_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('media','local_attachment')),source_id TEXT NOT NULL,object_key TEXT NOT NULL,PRIMARY KEY(project_id,contact_id,kind,source_id));

ALTER TABLE inbound_emails ADD COLUMN automatic INTEGER NOT NULL DEFAULT 0 CHECK (automatic IN (0,1));
ALTER TABLE inbound_emails ADD COLUMN evidence_json TEXT;
ALTER TABLE inbound_emails ADD COLUMN local_id TEXT;
ALTER TABLE inbound_emails ADD COLUMN message_id TEXT;
CREATE INDEX IF NOT EXISTS inbound_emails_local ON inbound_emails(project_id,local_id);

-- Dedicated edition credentials never enter sessions. Receipts retain hashes, not content.
CREATE TABLE edition_clients(id TEXT NOT NULL,project_id TEXT NOT NULL,origin TEXT NOT NULL,redirect_uri TEXT NOT NULL,allow_loopback INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(project_id,id));
