-- Closed is the terminal lifecycle boundary. New installations and upgrades both
-- get the default; leads can pause it or publish an edited immutable version.
INSERT INTO workflow_rules(id,project_id,name,kind,position,state,draft_json,published_version,owner_id,created_at,updated_at)
 SELECT 'workflow:auto-close:'||id,id,'Close solved tickets after 4 days','time',1000,'published','{"name":"Close solved tickets after 4 days","kind":"time","position":1000,"conditions":{"all":[{"field":"status_category","op":"eq","value":"solved"}],"any":[]},"time":{"field":"solved_at","hours":96},"actions":[{"type":"status","status_id":"closed"}]}',1,'system',CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM projects;
