-- WIDGET-001: the workspace's away reply (away-reply.ts, actor_role 'system') is the workspace speaking, not a reply.
-- Automations: its revision bump journals no event, so no rule runs on it, and beside a ticket change it is never an
-- operator reply. Outcomes: it is not an answer, so an AI-resolved conversation that got it records 'ai'.
-- Each trigger keeps every other byte of its definition (150; 195's CASE boundaries for the Wrangler SQL splitter).
DROP TRIGGER workflow_changed;
CREATE TRIGGER workflow_changed AFTER UPDATE OF revision,status_id,status_category,priority,assigned_to,group_id,subject,channel ON conversations WHEN OLD.last_message_id IS NOT NULL AND NEW.last_message_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM contact_erasures e WHERE e.project_id=NEW.project_id AND e.contact_id=NEW.contact_id) AND ((NEW.revision<>OLD.revision AND (SELECT actor_role FROM messages WHERE id=NEW.last_message_id) IS NOT 'system') OR NEW.status_id<>OLD.status_id OR NEW.status_category<>OLD.status_category OR NEW.priority<>OLD.priority OR NEW.assigned_to IS NOT OLD.assigned_to OR NEW.group_id IS NOT OLD.group_id OR NEW.subject<>OLD.subject OR NEW.channel<>OLD.channel) BEGIN
 INSERT OR IGNORE INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) VALUES((SELECT next_id FROM workflow_event_sequence WHERE id=1),CASE WHEN NEW.revision<>OLD.revision THEN 'message:'||NEW.last_message_id ELSE 'changed:'||lower(hex(randomblob(16))) END,NEW.project_id,NEW.id,CASE WHEN NEW.revision<>OLD.revision AND (SELECT actor_role FROM messages WHERE id=NEW.last_message_id)='contact' THEN 'customer_reply' WHEN NEW.revision<>OLD.revision AND (SELECT actor_role FROM messages WHERE id=NEW.last_message_id) IS NOT 'system' THEN 'operator_reply' ELSE 'changed' END,NEW.updated_at,NEW.ticket_source,NEW.revision,NEW.last_message_id,NEW.ticket_version,json_object('status_id',OLD.status_id,'status_category',OLD.status_category,'assigned_to',OLD.assigned_to,'group_id',OLD.group_id,'subject',OLD.subject,'priority',OLD.priority,'channel',OLD.channel,'brand_id',OLD.brand_id,'requester_id',OLD.requester_id,'contact_id',OLD.contact_id,'revision',OLD.revision,'last_message_id',OLD.last_message_id,'ticket_version',OLD.ticket_version),json_patch(json_object('status_id',NEW.status_id,'status_category',NEW.status_category,'assigned_to',NEW.assigned_to,'group_id',NEW.group_id,'subject',NEW.subject,'priority',NEW.priority,'channel',NEW.channel,'brand_id',NEW.brand_id,'requester_id',NEW.requester_id,'contact_id',NEW.contact_id,'revision',NEW.revision,'last_message_id',NEW.last_message_id,'ticket_version',NEW.ticket_version),json_object('message_id',CASE WHEN NEW.revision<>OLD.revision THEN NEW.last_message_id ELSE NULL END,'actor_role',CASE WHEN NEW.revision<>OLD.revision THEN (SELECT actor_role FROM messages WHERE id=NEW.last_message_id) ELSE NULL END,'is_note',0)));
END;
DROP TRIGGER conversation_record_resolution;
CREATE TRIGGER conversation_record_resolution AFTER UPDATE OF resolved_at ON conversations WHEN NEW.resolved_at IS NOT NULL AND (OLD.resolved_at IS NULL OR NEW.revision>OLD.revision) AND EXISTS(SELECT 1 FROM conversation_tracking WHERE conversation_id=NEW.id) BEGIN
 UPDATE conversation_resolutions SET reopened_at=NEW.updated_at WHERE OLD.resolved_at IS NOT NULL AND conversation_id=NEW.id AND ordinal=(SELECT MAX(ordinal) FROM conversation_resolutions WHERE conversation_id=NEW.id) AND reopened_at IS NULL;
 INSERT INTO conversation_resolutions(id,project_id,conversation_id,contact_id,ordinal,resolved_at,resolved_revision,cycle_start_revision,outcome,evidence_json)
 SELECT lower(hex(randomblob(16))),NEW.project_id,NEW.id,NEW.contact_id,COALESCE((SELECT MAX(ordinal)+1 FROM conversation_resolutions WHERE conversation_id=NEW.id),1),NEW.resolved_at,NEW.revision,t.cycle_start_revision,
 CASE
  WHEN EXISTS(SELECT 1 FROM messages m JOIN message_authorship a ON a.message_id=m.id WHERE m.conversation_id=NEW.id AND m.revision>t.cycle_start_revision AND m.revision<=NEW.revision AND a.kind='assisted' AND COALESCE(a.source_kind,'')<>'insight') THEN 'assisted'
  WHEN EXISTS(SELECT 1 FROM messages m JOIN message_authorship a ON a.message_id=m.id WHERE m.conversation_id=NEW.id AND m.revision>t.cycle_start_revision AND m.revision<=NEW.revision AND a.kind='human' AND COALESCE(a.source_kind,'')<>'insight') THEN 'human'
  WHEN t.cycle_history_complete=1 AND NEW.assigned_to IS NULL
   AND EXISTS(SELECT 1 FROM messages m JOIN message_authorship a ON a.message_id=m.id WHERE m.conversation_id=NEW.id AND m.revision>t.cycle_start_revision AND m.revision<=NEW.revision AND a.kind='ai' AND COALESCE(a.source_kind,'')<>'insight')
   AND NOT EXISTS(SELECT 1 FROM messages m LEFT JOIN message_authorship a ON a.message_id=m.id WHERE m.conversation_id=NEW.id AND m.revision>t.cycle_start_revision AND m.revision<=NEW.revision AND m.actor_role NOT IN ('contact','system') AND COALESCE(a.source_kind,'')<>'insight' AND COALESCE(a.kind,'unknown')<>'ai')
   AND NOT EXISTS(SELECT 1 FROM conversation_handoffs h WHERE h.conversation_id=NEW.id AND h.cycle_epoch=t.cycle_epoch) THEN 'ai'
  ELSE 'unknown' END ,
 json_object('historyComplete',t.cycle_history_complete,'messages',json((SELECT json_group_array(json_object('id',m.id,'kind',COALESCE(a.kind,'unknown'),'source',a.source_kind,'sourceId',a.source_id)) FROM messages m LEFT JOIN message_authorship a ON a.message_id=m.id WHERE m.conversation_id=NEW.id AND m.revision>t.cycle_start_revision AND m.revision<=NEW.revision AND m.actor_role NOT IN ('contact','system') AND COALESCE(a.source_kind,'')<>'insight')))
 FROM conversation_tracking t WHERE t.conversation_id=NEW.id;
 UPDATE conversation_tracking SET first_resolved_at= CASE WHEN initial_history_complete=1 THEN COALESCE(first_resolved_at,NEW.resolved_at) ELSE first_resolved_at END ,cycle_start_revision=NEW.revision,cycle_start_at=NEW.resolved_at,cycle_history_complete=1 WHERE conversation_id=NEW.id;
END;

-- Campaign configuration and consented, minimal attribution. No page contents or query strings.
CREATE TABLE widget_campaigns(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,revision INTEGER NOT NULL,config_json TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(project_id,id));
