CREATE TRIGGER workflow_ticket_field_values_insert AFTER INSERT ON ticket_field_values WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.conversation_id) AND NOT EXISTS(SELECT 1 FROM conversations c JOIN contact_erasures er ON er.project_id=c.project_id AND er.contact_id=c.contact_id WHERE c.id=NEW.conversation_id) BEGIN
 INSERT INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) SELECT (SELECT next_id FROM workflow_event_sequence WHERE id=1),'changed:'||lower(hex(randomblob(16))),c.project_id,c.id,'changed',coalesce((SELECT max(at) FROM ticket_history WHERE conversation_id=c.id),c.updated_at),c.ticket_source,c.revision,c.last_message_id,c.ticket_version,'{}',json_object('status_id',c.status_id,'status_category',c.status_category,'assigned_to',c.assigned_to,'group_id',c.group_id,'subject',c.subject,'priority',c.priority,'channel',c.channel,'brand_id',c.brand_id,'requester_id',c.requester_id,'contact_id',c.contact_id,'revision',c.revision,'last_message_id',c.last_message_id,'ticket_version',c.ticket_version,'tags',json((SELECT json_group_array(tag_id) FROM conversation_tags WHERE conversation_id=c.id)),'fields',json((SELECT json_group_object(field_id,json(value_json)) FROM ticket_field_values WHERE conversation_id=c.id))) FROM conversations c WHERE c.id=NEW.conversation_id AND c.last_message_id IS NOT NULL;
END;
CREATE TRIGGER workflow_ticket_field_values_update AFTER UPDATE ON ticket_field_values WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.conversation_id) AND NOT EXISTS(SELECT 1 FROM conversations c JOIN contact_erasures er ON er.project_id=c.project_id AND er.contact_id=c.contact_id WHERE c.id=NEW.conversation_id) BEGIN
 INSERT INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) SELECT (SELECT next_id FROM workflow_event_sequence WHERE id=1),'changed:'||lower(hex(randomblob(16))),c.project_id,c.id,'changed',coalesce((SELECT max(at) FROM ticket_history WHERE conversation_id=c.id),c.updated_at),c.ticket_source,c.revision,c.last_message_id,c.ticket_version,'{}',json_object('status_id',c.status_id,'status_category',c.status_category,'assigned_to',c.assigned_to,'group_id',c.group_id,'subject',c.subject,'priority',c.priority,'channel',c.channel,'brand_id',c.brand_id,'requester_id',c.requester_id,'contact_id',c.contact_id,'revision',c.revision,'last_message_id',c.last_message_id,'ticket_version',c.ticket_version,'tags',json((SELECT json_group_array(tag_id) FROM conversation_tags WHERE conversation_id=c.id)),'fields',json((SELECT json_group_object(field_id,json(value_json)) FROM ticket_field_values WHERE conversation_id=c.id))) FROM conversations c WHERE c.id=NEW.conversation_id AND c.last_message_id IS NOT NULL;
END;
CREATE TRIGGER workflow_ticket_field_values_delete AFTER DELETE ON ticket_field_values WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=OLD.project_id AND f.conversation_id=OLD.conversation_id) AND NOT EXISTS(SELECT 1 FROM conversations c JOIN contact_erasures er ON er.project_id=c.project_id AND er.contact_id=c.contact_id WHERE c.id=OLD.conversation_id) BEGIN
 INSERT INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) SELECT (SELECT next_id FROM workflow_event_sequence WHERE id=1),'changed:'||lower(hex(randomblob(16))),c.project_id,c.id,'changed',coalesce((SELECT max(at) FROM ticket_history WHERE conversation_id=c.id),c.updated_at),c.ticket_source,c.revision,c.last_message_id,c.ticket_version,'{}',json_object('status_id',c.status_id,'status_category',c.status_category,'assigned_to',c.assigned_to,'group_id',c.group_id,'subject',c.subject,'priority',c.priority,'channel',c.channel,'brand_id',c.brand_id,'requester_id',c.requester_id,'contact_id',c.contact_id,'revision',c.revision,'last_message_id',c.last_message_id,'ticket_version',c.ticket_version,'tags',json((SELECT json_group_array(tag_id) FROM conversation_tags WHERE conversation_id=c.id)),'fields',json((SELECT json_group_object(field_id,json(value_json)) FROM ticket_field_values WHERE conversation_id=c.id))) FROM conversations c WHERE c.id=OLD.conversation_id AND c.last_message_id IS NOT NULL;
END;

