INSERT INTO csat_response_history_messaging(id,resolution_id,project_id,contact_id,channel,scale,score,reason,comment,revision,created_at,response_surface,recovery) SELECT id,resolution_id,project_id,contact_id,channel,scale,score,reason,comment,revision,created_at,response_surface,recovery FROM csat_response_history;
