);
CREATE INDEX mobile_frontiers_device ON mobile_frontiers(device_id,expires_at);
CREATE TABLE mobile_commands (
 device_id TEXT NOT NULL REFERENCES mobile_devices(id) ON DELETE CASCADE,
 local_id TEXT NOT NULL,
