-- The contacts list reads a bounded number of rows on a large workspace. contact_tallies counts each workspace's
-- live contacts (exactly the list's count without a term: is_deleted is not 1; a workspace with none has no row),
-- so the page's total reads one row. Each sort and direction has an index in the list's own order (the sort key verbatim, then id ascending in
-- either direction; contacts_name_order in 313 holds name ascending), so a page, and a page after or before a
-- boundary contact, walks its order and stops after its rows. The tally is derived: the migration fills it,
-- triggers on contacts keep it current (imports write rows with plain INSERTs, the widget patches metadata_json),
-- and a restore rebuilds it from the restored rows (scripts/installer/contact-bounds-sql.mjs).
CREATE INDEX contacts_last_seen_asc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER),id);
CREATE INDEX contacts_last_seen_desc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER) DESC,id);
CREATE INDEX contacts_name_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE DESC,id);
CREATE INDEX contacts_email_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE,id);
CREATE INDEX contacts_email_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE DESC,id);
CREATE INDEX contacts_country_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE,id);
CREATE INDEX contacts_country_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE DESC,id);
CREATE TABLE contact_tallies(project_id TEXT PRIMARY KEY NOT NULL,total INTEGER NOT NULL);
INSERT INTO contact_tallies(project_id,total) SELECT project_id,count(*) FROM contacts WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 GROUP BY project_id;
CREATE TRIGGER contact_tallies_insert AFTER INSERT ON contacts WHEN coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1 BEGIN
 INSERT INTO contact_tallies(project_id,total) VALUES(NEW.project_id,1) ON CONFLICT(project_id) DO UPDATE SET total=total+1;
END;
CREATE TRIGGER contact_tallies_delete AFTER DELETE ON contacts WHEN coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1 BEGIN
 UPDATE contact_tallies SET total=total-1 WHERE project_id=OLD.project_id;
 DELETE FROM contact_tallies WHERE project_id=OLD.project_id AND total<=0;
END;
-- A soft delete, an erasure or an undelete flips is_deleted; a move changes the workspace. Other writes change nothing.
CREATE TRIGGER contact_tallies_update AFTER UPDATE OF metadata_json,project_id ON contacts WHEN OLD.project_id IS NOT NEW.project_id OR (coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1) IS NOT (coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1) BEGIN
 UPDATE contact_tallies SET total=total-1 WHERE project_id=OLD.project_id AND coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1;
 DELETE FROM contact_tallies WHERE project_id=OLD.project_id AND total<=0;
 INSERT INTO contact_tallies(project_id,total) SELECT NEW.project_id,1 WHERE coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1 ON CONFLICT(project_id) DO UPDATE SET total=total+1;
END;
-- A term's walk reads only the contacts a non-empty term can match: live, with a name, email, provided name or
-- provided email. Hidden widget drafts have none of them, so neither a broad term's page nor a short term's count
-- steps over them. The list adds this exact predicate to a term's statements (a match implies it), so the planner
-- proves each partial index usable.
CREATE INDEX contacts_searchable_last_seen_asc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER),id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_last_seen_desc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER) DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_name_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_name_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_email_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_email_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_country_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_country_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
-- contact_search: each live contact with an identity value, scoped to its workspace (the scope column holds the
-- workspace id between two U+0001 characters; a deleted contact or one without identity values has none), with
-- exactly the four values the list searches through SQLite's lower(). A phrase of three or more characters there is
-- the list's ASCII case-insensitive substring match, so a term's total within a workspace is its number of matches,
-- one row each. Each entry carries the contact's id and its four sort keys (unindexed, read through the view), so a
-- term's matches are read with their keys at one row each and ordered whatever their number, and each sort's order
-- text in a band column (indexed; src/modules/management/contact-bands.ts): a text key through lower(), a last seen
-- as the first ten hex digits of its value with the sign bit flipped, between two U+0002 and a U+0003. A phrase of
-- its first characters asks for a band, one stretch of the order, so a page without a total finds a sparse term's
-- matches without reading the stretches between them. Like 310 it is derived:
-- the migration fills it, triggers keep it current, 'rebuild' restores it from contacts, and integrity-check with
-- rank=1 validates it against them; secure-delete removes a changed or erased identity's trigrams from storage.
CREATE VIEW contact_search_identity AS SELECT rowid AS rowid,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(1)||project_id||char(1) ELSE '' END AS scope,lower(coalesce(name,'')) AS name,lower(coalesce(email,'')) AS email,lower(coalesce(json_extract(metadata_json,'$.provided_name'),'')) AS provided_name,lower(coalesce(json_extract(metadata_json,'$.provided_email'),'')) AS provided_email,id AS contact_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER) AS last_seen_key,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') AS name_key,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') AS email_key,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') AS country_key,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)||char(3) ELSE '' END AS last_seen_band,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||CASE WHEN typeof(coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'')),1,1000000000) ELSE '' END||char(3) ELSE '' END AS name_band,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||CASE WHEN typeof(coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'')),1,1000000000) ELSE '' END||char(3) ELSE '' END AS email_band,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||CASE WHEN typeof(coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END||char(3) ELSE '' END AS country_band FROM contacts;
CREATE VIRTUAL TABLE contact_search USING fts5(scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id UNINDEXED,last_seen_key UNINDEXED,name_key UNINDEXED,email_key UNINDEXED,country_key UNINDEXED,content='contact_search_identity',content_rowid='rowid',tokenize='trigram case_sensitive 1');
INSERT INTO contact_search(contact_search,rank) VALUES('secure-delete',1);
INSERT INTO contact_search(contact_search) VALUES('rebuild');
CREATE TRIGGER contact_search_insert AFTER INSERT ON contacts BEGIN
 INSERT INTO contact_search(rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key) SELECT rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key FROM contact_search_identity WHERE rowid=NEW.rowid;
