END;
-- The widget rewrites metadata_json on every session; only a changed identity value, workspace, deleted flag or order
-- text reindexes (a last seen's order text changes once in 2^24 ms; the keys are read through the view).
CREATE TRIGGER contact_search_unindex BEFORE UPDATE OF name,email,metadata_json,project_id ON contacts WHEN OLD.project_id IS NOT NEW.project_id OR OLD.name IS NOT NEW.name OR OLD.email IS NOT NEW.email OR json_extract(OLD.metadata_json,'$.provided_name') IS NOT json_extract(NEW.metadata_json,'$.provided_name') OR json_extract(OLD.metadata_json,'$.provided_email') IS NOT json_extract(NEW.metadata_json,'$.provided_email') OR (coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1) IS NOT (coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1) OR (substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(OLD.metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(OLD.metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)) IS NOT (substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(NEW.metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(NEW.metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_name'),''),OLD.name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_name'),''),OLD.name,'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_name'),''),NEW.name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_name'),''),NEW.name,'')),1,1000000000) ELSE '' END) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_email'),''),OLD.email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_email'),''),OLD.email,'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_email'),''),NEW.email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_email'),''),NEW.email,'')),1,1000000000) ELSE '' END) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.country_name'),''),json_extract(OLD.metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.country_name'),''),json_extract(OLD.metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.country_name'),''),json_extract(NEW.metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.country_name'),''),json_extract(NEW.metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END) BEGIN
 INSERT INTO contact_search(contact_search,rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key) SELECT 'delete',rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key FROM contact_search_identity WHERE rowid=OLD.rowid;
END;
