-- The cutover page reads a bounded number of rows on a large imported workspace. Its counts were each a walk over the
-- workspace's conversations (the legacy journal has no workspace column, and a widget arrival is told apart from a
-- hidden draft only by its messages). Each counted set is kept here instead, one row per member, with a tally per
-- workspace, so the page reads a tally, the runs that touched the workspace and the widget arrivals after a moment:
-- cutover_zendesk_conversations: a conversation Move in imported from Zendesk that is still in its workspace
--  (cutover/counts.ts zendeskImported).
-- cutover_legacy_conversations: a workspace conversation and each run whose journal maps it (counts.ts legacy);
--  cutover_legacy_runs counts them per workspace and run, so the last sweep reads the runs, live.
-- cutover_widget_arrivals: a conversation a visitor started through the widget and wrote in, with its creation time
--  (counts.ts widgetArrivals without its moment).
-- cutover_tallies: per workspace, the Zendesk and legacy conversations and the widget arrivals of all time.
-- Every row is derived: the migration fills them, and triggers on every table they derive from keep them current
-- (imports write rows with plain INSERTs, so write-path code could not). A restore rebuilds them from the restored rows.
CREATE TABLE cutover_tallies(project_id TEXT PRIMARY KEY,zendesk INTEGER NOT NULL DEFAULT 0,legacy INTEGER NOT NULL DEFAULT 0,widget INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE cutover_zendesk_conversations(conversation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE cutover_legacy_conversations(conversation_id TEXT NOT NULL,run_id TEXT NOT NULL,project_id TEXT NOT NULL,PRIMARY KEY(conversation_id,run_id)) WITHOUT ROWID;
CREATE TABLE cutover_legacy_runs(project_id TEXT NOT NULL,run_id TEXT NOT NULL,conversations INTEGER NOT NULL,PRIMARY KEY(project_id,run_id)) WITHOUT ROWID;
CREATE TABLE cutover_widget_arrivals(conversation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,created_at INTEGER NOT NULL) WITHOUT ROWID;
-- The arrivals after a moment are one range of this index.
CREATE INDEX cutover_widget_arrivals_since ON cutover_widget_arrivals(project_id,created_at);
-- The tallies follow their sets. A conversation counts once for legacy however many runs map it.
CREATE TRIGGER cutover_zendesk_added AFTER INSERT ON cutover_zendesk_conversations BEGIN
 INSERT INTO cutover_tallies(project_id) SELECT NEW.project_id WHERE NOT EXISTS(SELECT 1 FROM cutover_tallies WHERE project_id=NEW.project_id);
 UPDATE cutover_tallies SET zendesk=zendesk+1 WHERE project_id=NEW.project_id;
END;
CREATE TRIGGER cutover_zendesk_removed AFTER DELETE ON cutover_zendesk_conversations BEGIN
 UPDATE cutover_tallies SET zendesk=zendesk-1 WHERE project_id=OLD.project_id;
 DELETE FROM cutover_tallies WHERE project_id=OLD.project_id AND zendesk=0 AND legacy=0 AND widget=0;
END;
CREATE TRIGGER cutover_widget_added AFTER INSERT ON cutover_widget_arrivals BEGIN
 INSERT INTO cutover_tallies(project_id) SELECT NEW.project_id WHERE NOT EXISTS(SELECT 1 FROM cutover_tallies WHERE project_id=NEW.project_id);
 UPDATE cutover_tallies SET widget=widget+1 WHERE project_id=NEW.project_id;
END;
CREATE TRIGGER cutover_widget_removed AFTER DELETE ON cutover_widget_arrivals BEGIN
 UPDATE cutover_tallies SET widget=widget-1 WHERE project_id=OLD.project_id;
 DELETE FROM cutover_tallies WHERE project_id=OLD.project_id AND zendesk=0 AND legacy=0 AND widget=0;
END;
CREATE TRIGGER cutover_legacy_added AFTER INSERT ON cutover_legacy_conversations BEGIN
 INSERT INTO cutover_legacy_runs(project_id,run_id,conversations) SELECT NEW.project_id,NEW.run_id,0 WHERE NOT EXISTS(SELECT 1 FROM cutover_legacy_runs WHERE project_id=NEW.project_id AND run_id=NEW.run_id);
 UPDATE cutover_legacy_runs SET conversations=conversations+1 WHERE project_id=NEW.project_id AND run_id=NEW.run_id;
 INSERT INTO cutover_tallies(project_id) SELECT NEW.project_id WHERE NOT EXISTS(SELECT 1 FROM cutover_tallies WHERE project_id=NEW.project_id);
 UPDATE cutover_tallies SET legacy=legacy+1 WHERE project_id=NEW.project_id AND NOT EXISTS(SELECT 1 FROM cutover_legacy_conversations l WHERE l.conversation_id=NEW.conversation_id AND l.run_id<>NEW.run_id);
END;
CREATE TRIGGER cutover_legacy_removed AFTER DELETE ON cutover_legacy_conversations BEGIN
 UPDATE cutover_legacy_runs SET conversations=conversations-1 WHERE project_id=OLD.project_id AND run_id=OLD.run_id;
 DELETE FROM cutover_legacy_runs WHERE project_id=OLD.project_id AND run_id=OLD.run_id AND conversations=0;
 UPDATE cutover_tallies SET legacy=legacy-1 WHERE project_id=OLD.project_id AND NOT EXISTS(SELECT 1 FROM cutover_legacy_conversations l WHERE l.conversation_id=OLD.conversation_id);
 DELETE FROM cutover_tallies WHERE project_id=OLD.project_id AND zendesk=0 AND legacy=0 AND widget=0;
END;
INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM move_in_conversations m JOIN conversations c ON c.id=m.conversation_id AND c.project_id=m.project_id WHERE m.vendor='zendesk';
INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM legacy_import_rows r JOIN conversations c ON c.id=r.source_id WHERE r.source_table='conversations' AND r.status='mapped';
INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
-- A conversation is added, changed or removed: each of its memberships is read again from its own rows.
CREATE TRIGGER cutover_conversation_added AFTER INSERT ON conversations BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id=NEW.id;
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id=NEW.id AND EXISTS(SELECT 1 FROM move_in_conversations m WHERE m.conversation_id=c.id AND m.project_id=c.project_id AND m.vendor='zendesk');
 DELETE FROM cutover_legacy_conversations WHERE conversation_id=NEW.id;
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM conversations c JOIN legacy_import_rows r ON r.source_table='conversations' AND r.source_id=c.id AND r.status='mapped' WHERE c.id=NEW.id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=NEW.id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_conversation_changed AFTER UPDATE OF id,project_id,created_at,channel,submitter_type,mailbox_id ON conversations WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.created_at IS NOT OLD.created_at OR NEW.channel IS NOT OLD.channel OR NEW.submitter_type IS NOT OLD.submitter_type OR NEW.mailbox_id IS NOT OLD.mailbox_id BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id IN (OLD.id,NEW.id);
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id IN (OLD.id,NEW.id) AND EXISTS(SELECT 1 FROM move_in_conversations m WHERE m.conversation_id=c.id AND m.project_id=c.project_id AND m.vendor='zendesk');
 DELETE FROM cutover_legacy_conversations WHERE conversation_id IN (OLD.id,NEW.id);
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM conversations c JOIN legacy_import_rows r ON r.source_table='conversations' AND r.source_id=c.id AND r.status='mapped' WHERE c.id IN (OLD.id,NEW.id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.id,NEW.id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.id,NEW.id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_conversation_removed AFTER DELETE ON conversations BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id=OLD.id;
 DELETE FROM cutover_legacy_conversations WHERE conversation_id=OLD.id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.id;
END;
-- Move in's record of a Zendesk import: the conversation counts as imported while both exist in one workspace, and an
-- imported conversation is never a widget arrival.
CREATE TRIGGER cutover_move_in_added AFTER INSERT ON move_in_conversations BEGIN
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id=NEW.conversation_id AND c.project_id=NEW.project_id AND NEW.vendor='zendesk' AND NOT EXISTS(SELECT 1 FROM cutover_zendesk_conversations z WHERE z.conversation_id=NEW.conversation_id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.conversation_id;
END;
CREATE TRIGGER cutover_move_in_changed AFTER UPDATE OF conversation_id,project_id,vendor ON move_in_conversations WHEN NEW.conversation_id IS NOT OLD.conversation_id OR NEW.project_id IS NOT OLD.project_id OR NEW.vendor IS NOT OLD.vendor BEGIN
