 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.conversation_id,NEW.conversation_id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_move_in_removed AFTER DELETE ON move_in_conversations BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id=OLD.conversation_id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.conversation_id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=OLD.conversation_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
