-- The legacy journal names a conversation by its source id, which a legacy conversation keeps natively. The importer
-- writes a conversation and its journal row in either order within a batch; whichever comes second links them. A
-- journaled conversation, mapped or not, is never a widget arrival.
CREATE TRIGGER cutover_journal_added AFTER INSERT ON legacy_import_rows WHEN NEW.source_table='conversations' BEGIN
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,NEW.run_id,c.project_id FROM conversations c WHERE c.id=NEW.source_id AND NEW.status='mapped' AND NOT EXISTS(SELECT 1 FROM cutover_legacy_conversations l WHERE l.conversation_id=NEW.source_id AND l.run_id=NEW.run_id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.source_id;
END;
CREATE TRIGGER cutover_journal_changed AFTER UPDATE OF run_id,source_table,source_id,status ON legacy_import_rows WHEN (NEW.source_table='conversations' OR OLD.source_table='conversations') AND (NEW.run_id IS NOT OLD.run_id OR NEW.source_table IS NOT OLD.source_table OR NEW.source_id IS NOT OLD.source_id OR NEW.status IS NOT OLD.status) BEGIN
 DELETE FROM cutover_legacy_conversations WHERE conversation_id IN (OLD.source_id,NEW.source_id);
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM conversations c JOIN legacy_import_rows r ON r.source_table='conversations' AND r.source_id=c.id AND r.status='mapped' WHERE c.id IN (OLD.source_id,NEW.source_id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.source_id,NEW.source_id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.source_id,NEW.source_id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_journal_removed AFTER DELETE ON legacy_import_rows WHEN OLD.source_table='conversations' BEGIN
 DELETE FROM cutover_legacy_conversations WHERE conversation_id=OLD.source_id AND run_id=OLD.run_id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.source_id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=OLD.source_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
