-- A reply or a ticket edit moves an entry in its orders and times in place; its facets follow.
CREATE TRIGGER inbox_entry_facets_moved AFTER UPDATE OF sort_at,created_at,updated_at ON inbox_entries WHEN NEW.sort_at IS NOT OLD.sort_at OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at BEGIN
 UPDATE inbox_facets SET sort_at=NEW.sort_at,created_at=NEW.created_at,updated_at=NEW.updated_at WHERE conversation_id=NEW.conversation_id;
END;
-- A tag added or removed (313 rewrites tags_key) rebuilds the entry's tag facets and tag sets; a time edited in
-- place moves its buckets. A counted column changed in place (313 never does) recounts every key of the entry.
CREATE TRIGGER inbox_entry_retagged AFTER UPDATE OF tags_key ON inbox_entries WHEN NEW.tags_key IS NOT OLD.tags_key AND NOT (NEW.conversation_id IS NOT OLD.conversation_id OR NEW.project_id IS NOT OLD.project_id OR NEW.group_id IS NOT OLD.group_id OR NEW.assigned_to IS NOT OLD.assigned_to OR NEW.unresolved IS NOT OLD.unresolved OR NEW.ai IS NOT OLD.ai OR NEW.snoozed IS NOT OLD.snoozed OR NEW.priority IS NOT OLD.priority OR NEW.status_category IS NOT OLD.status_category OR NEW.channel IS NOT OLD.channel OR NEW.status_id IS NOT OLD.status_id) BEGIN
 DELETE FROM inbox_facets WHERE conversation_id=NEW.conversation_id AND kind IN ('t','w');
