CREATE TRIGGER inbox_entry_resubjected AFTER UPDATE OF subject,project_id ON inbox_entries WHEN NEW.subject IS NOT OLD.subject OR NEW.project_id IS NOT OLD.project_id BEGIN
 INSERT INTO inbox_subject_search(inbox_subject_search,rowid,subject_text,workspace) SELECT 'delete',OLD.rowid,lower(OLD.subject),'|'||OLD.project_id||'|' WHERE OLD.subject IS NOT NULL AND OLD.subject<>'';
